//! Note bodies. Pure.
//!
//! These are skeleton templates: they show identities, kinds, revisions and
//! snapshot markers only, and never authored text, so they need no escaping
//! and cannot leak classified content. The entity note template, case
//! Overview and `Start Here.md` work replaces them behind the same functions.

use std::fmt::Write as _;

use investigation_core::{identity::Id, state::Record};

use crate::{
    CaseSnapshot, Generation, RENDERER_VERSION, RenderError, VerifiedSnapshot, ViewPolicy, layout,
};

/// Marks every generated file as a tool-owned projection.
pub const BANNER: &str = "> [!note] Generated by Investigation from a verified snapshot.\n\
> This file is a tool-owned projection: edits here are drift, not recorded changes.\n\
> Write in `Notes/`, `Boards/` or `Inbox/` instead.\n";

fn heading(out: &mut String, title: &str) {
    let _ = write!(out, "# {title}\n\n{BANNER}\n");
}

fn marker(out: &mut String, case: &CaseSnapshot, generation: &Generation) {
    let head = case.head();
    let _ = writeln!(
        out,
        "- Snapshot: sequence {}, head `{}`",
        head.sequence, head.head_hash
    );
    let _ = writeln!(out, "- Generation: `{}`", generation.id());
}

fn withheld(out: &mut String, policy: &ViewPolicy) {
    let _ = writeln!(
        out,
        "- Content: withheld by the view policy for the `{}` audience",
        policy.audience.as_str()
    );
}

fn case_link(case_id: Id) -> Result<String, RenderError> {
    Ok(layout::wikilink(
        &layout::case_overview(case_id)?,
        &case_id.to_string(),
    ))
}

pub fn record_note(
    case: &CaseSnapshot,
    record: &Record,
    policy: &ViewPolicy,
    generation: &Generation,
) -> Result<String, RenderError> {
    let header = &record.header;
    let mut out = String::new();
    heading(&mut out, &header.id.to_string());
    if let Some((_, name)) = layout::record_kind(header.id.kind()) {
        let _ = writeln!(out, "- Kind: {name}");
    }
    let _ = writeln!(out, "- Case: {}", case_link(case.case_id())?);
    let _ = writeln!(out, "- Revision: {}", header.revision.0);
    if !policy.admits(&header.classification) {
        withheld(&mut out, policy);
    }
    marker(&mut out, case, generation);
    Ok(out)
}

pub fn case_overview(
    case: &CaseSnapshot,
    policy: &ViewPolicy,
    generation: &Generation,
) -> Result<String, RenderError> {
    let case_id = case.case_id();
    let state = case.state();
    let mut out = String::new();
    heading(&mut out, &case_id.to_string());
    if state
        .current(case_id)
        .is_some_and(|record| !policy.admits(&record.header.classification))
    {
        withheld(&mut out, policy);
    }
    marker(&mut out, case, generation);
    out.push_str("\n## Records\n");
    let mut any = false;
    for &(kind, folder, _) in layout::RECORD_FOLDERS {
        let mut records = state
            .records()
            .filter(|record| record.header.id.kind() == kind)
            .peekable();
        if records.peek().is_none() {
            continue;
        }
        any = true;
        let _ = write!(out, "\n### {folder}\n\n");
        for record in records {
            let id = record.header.id;
            if let Some(path) = layout::record_note(case_id, id)? {
                let _ = writeln!(
                    out,
                    "- {} (revision {})",
                    layout::wikilink(&path, &id.to_string()),
                    record.header.revision.0
                );
            }
        }
    }
    if !any {
        out.push_str("\nNo records beyond the case itself.\n");
    }
    Ok(out)
}

pub fn start_here(
    snapshot: &VerifiedSnapshot,
    policy: &ViewPolicy,
    generation: &Generation,
) -> Result<String, RenderError> {
    let mut out = String::new();
    heading(&mut out, "Start Here");
    let _ = writeln!(out, "- Generation: `{}`", generation.id());
    let _ = writeln!(out, "- Renderer: `{RENDERER_VERSION}`");
    let _ = writeln!(out, "- View audience: `{}`", policy.audience.as_str());
    out.push_str("\n## Cases\n\n");
    let mut any = false;
    for case in snapshot.cases() {
        any = true;
        let head = case.head();
        let _ = writeln!(
            out,
            "- {}: sequence {}, head `{}`",
            case_link(case.case_id())?,
            head.sequence,
            head.head_hash
        );
    }
    if !any {
        out.push_str("No cases recorded yet.\n");
    }
    out.push_str(
        "\n## Human-owned folders\n\n\
         `Notes/`, `Boards/` and `Inbox/` belong to you. Rendering never writes into them.\n",
    );
    Ok(out)
}
